<?php require 'config.php'; if(isset($_SESSION['user'])){header('Location:index.php');exit;} if($_SERVER['REQUEST_METHOD']==='POST'){ $u=trim($_POST['username']??''); $p=$_POST['password']??''; $st=$pdo->prepare('SELECT * FROM users WHERE username=? LIMIT 1'); $st->execute([$u]); $user=$st->fetch(); if($user && password_verify($p,$user['password'])){ $_SESSION['user']=$user['username']; header('Location:index.php'); exit;} $error='Неверный логин или пароль'; } ?>
<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Вход в админку</title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css"><link rel="stylesheet" href="style.css"></head><body class="d-flex align-items-center justify-content-center vh-100"><div class="card p-4 fade-in" style="max-width:420px;width:100%"><h3 class="mb-3 text-center">Вход</h3><?php if(!empty($error)):?><div class="alert alert-danger"><?= $error ?></div><?php endif; ?><form method="post"><div class="mb-3"><label class="form-label">Логин</label><input name="username" class="form-control" required></div><div class="mb-3"><label class="form-label">Пароль</label><input type="password" name="password" class="form-control" required></div><button class="btn btn-primary w-100">Войти</button></form></div></body></html>